INSERT IGNORE INTO `games` (`game_id`, `rawg_id`, `steam_app_id`, `title`, `slug`, `description`, `cover_url`, `release_date`, `release_year`, `genres`, `platforms`, `is_active`, `rawg_synced_at`, `steam_synced_at`, `created_at`, `updated_at`) VALUES
	(1, 3498, 3240220, 'Grand Theft Auto V', 'grand-theft-auto-v', 'Rockstar Games went bigger, since their previous installment of the series. You get the complicated and realistic world-building from Liberty City of GTA4 in the setting of lively and diverse Los Santos, from an old fan favorite GTA San Andreas. 561 different vehicles (including every transport you can operate) and the amount is rising with every update. \nSimultaneous storytelling from three unique perspectives: \nFollow Michael, ex-criminal living his life of leisure away from the past, Franklin, a kid that seeks the better future, and Trevor, the exact past Michael is trying to run away from. \nGTA Online will provide a lot of additional challenge even for the experienced players, coming fresh from the story mode. Now you will have other players around that can help you just as likely as ruin your mission. Every GTA mechanic up to date can be experienced by players through the unique customizable character, and community content paired with the leveling system tends to keep everyone busy and engaged.\n\nEspañol\nRockstar Games se hizo más grande desde su entrega anterior de la serie. Obtienes la construcción del mundo complicada y realista de Liberty City de GTA4 en el escenario de Los Santos, un viejo favorito de los fans, GTA San Andreas. 561 vehículos diferentes (incluidos todos los transportes que puede operar) y la cantidad aumenta con cada actualización.\nNarración simultánea desde tres perspectivas únicas:\nSigue a Michael, ex-criminal que vive su vida de ocio lejos del pasado, Franklin, un niño que busca un futuro mejor, y Trevor, el pasado exacto del que Michael está tratando de huir.\nGTA Online proporcionará muchos desafíos adicionales incluso para los jugadores experimentados, recién llegados del modo historia. Ahora tendrás otros jugadores cerca que pueden ayudarte con la misma probabilidad que arruinar tu misión. Los jugadores pueden experimentar todas las mecánicas de GTA actualizadas a través del personaje personalizable único, y el contenido de la comunidad combinado con el sistema de nivelación tiende a mantener a todos ocupados y comprometidos.', 'https://media.rawg.io/media/games/20a/20aa03a10cda45239fe22d035c0ebe64.jpg', '2013-09-17', 2013, '["Action"]', '["PlayStation 5", "Xbox Series S/X", "PlayStation 3", "PC", "PlayStation 4", "Xbox 360", "Xbox One"]', 0, '2026-09-16 10:48:53', '2026-09-16 04:48:53', '2026-09-16 02:48:46', '2026-09-16 03:06:04'),
	(2, 3328, 5006530, 'The Witcher 3: Wild Hunt', 'the-witcher-3-wild-hunt', 'The third game in a series, it holds nothing back from the player. Open world adventures of the renowned monster slayer Geralt of Rivia are now even on a larger scale. Following the source material more accurately, this time Geralt is trying to find the child of the prophecy, Ciri while making a quick coin from various contracts on the side. Great attention to the world building above all creates an immersive story, where your decisions will shape the world around you.\n\nCD Project Red are infamous for the amount of work they put into their games, and it shows, because aside from classic third-person action RPG base game they provided 2 massive DLCs with unique questlines and 16 smaller DLCs, containing extra quests and items.\n\nPlayers praise the game for its atmosphere and a wide open world that finds the balance between fantasy elements and realistic and believable mechanics, and the game deserved numerous awards for every aspect of the game, from music to direction.', 'https://media.rawg.io/media/games/618/618c2031a07bbff6b4f611f10b6bcdbc.jpg', '2015-05-18', 2015, '["Action", "RPG"]', '["PlayStation 5", "Xbox Series S/X", "macOS", "PlayStation 4", "Nintendo Switch", "PC", "Xbox One"]', 0, '2026-09-16 11:06:30', '2026-09-16 05:06:30', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(3, 4200, 620, 'Portal 2', 'portal-2', 'Portal 2 is a first-person puzzle game developed by Valve Corporation and released on April 19, 2011 on Steam, PS3 and Xbox 360. It was published by Valve Corporation in digital form and by Electronic Arts in physical form. \n\nIts plot directly follows the first game\'s, taking place in the Half-Life universe. You play as Chell, a test subject in a research facility formerly ran by the company Aperture Science, but taken over by an evil AI that turned upon its creators, GladOS. After defeating GladOS at the end of the first game but failing to escape the facility, Chell is woken up from a stasis chamber by an AI personality core, Wheatley, as the unkempt complex is falling apart. As the two attempt to navigate through the ruins and escape, they stumble upon GladOS, and accidentally re-activate her...\n\nPortal 2\'s core mechanics are very similar to the first game\'s ; the player must make their way through several test chambers which involve puzzles. For this purpose, they possess a Portal Gun, a weapon capable of creating teleportation portals on white surfaces. This seemingly simple mechanic and its subtleties coupled with the many different puzzle elements that can appear in puzzles allows the game to be easy to start playing, yet still feature profound gameplay. The sequel adds several new puzzle elements, such as gel that can render surfaces bouncy or allow you to accelerate when running on them.\n\nThe game is often praised for its gameplay, its memorable dialogue and writing and its aesthetic. Both games in the series are responsible for inspiring most puzzle games succeeding them, particularly first-person puzzle games. The series, its characters and even its items such as the portal gun and the companion cube have become a cultural icon within gaming communities.\n\nPortal 2 also features a co-op mode where two players take on the roles of robots being led through tests by GladOS, as well as an in-depth level editor.', 'https://media.rawg.io/media/games/2ba/2bac0e87cf45e5b508f227d281c9252a.jpg', '2011-04-18', 2011, '["Shooter", "Puzzle"]', '["PlayStation 3", "PC", "Xbox 360", "Linux", "macOS", "Xbox One"]', 0, '2026-09-16 11:06:31', '2026-09-16 05:06:31', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(4, 4291, NULL, 'Counter-Strike: Global Offensive', 'counter-strike-global-offensive', 'Counter-Strike is a multiplayer phenomenon in its simplicity. No complicated narratives to explain the source of the conflict, no futuristic and alien threats, but counter-terrorists against terrorists. Arena shooter at its core, CS:GO provides you with various methods of disposing enemies and reliant on cooperation within the team. During the round of the classical clash mode, you will gradually receive currency to purchase different equipment. Each player can carry a primary weapon, secondary pistol, knife and a set of grenades, which all can change the battle if wielded by the skilled player. \r\nObjectives are clear and vary from map to map, from game mode to game mode. Stop the terrorists from planting explosives, stop the counter-terrorist from retrieving the hostages, kill everyone who isn’t you and just perform the best with.\r\nCS:GO is one of the major cybersport discipline, which makes playing it more exciting to some players. Aside from purchasing the game, CS:GO is infamous for its loot case system, that requires players to purchase keys, in order to open said cases. Customization items consist of weapon skins, weapon stickers, and sprays that do not affect gameplay and have purely visual value to the player.', 'https://media.rawg.io/media/games/736/73619bd336c894d6941d926bfd563946.jpg', '2012-08-21', 2012, '["Shooter"]', '["PC", "Linux", "Xbox 360", "PlayStation 3"]', 0, '2026-09-16 11:06:32', NULL, '2026-09-16 02:48:46', '2026-09-16 03:06:32'),
	(6, 5286, 391220, 'Tomb Raider', 'tomb-raider', 'A cinematic revival of the series in its action third person form, Tomb Rider follows Lara in her least experience period of life – her youth. Heavily influenced by Naughty Dog’s “Uncharted”, the game is a mix of everything, from stealth and survival to combat and QTE action scenes.\r\nYoung Lara Croft arrives on the Yamatai, lost island near Japan, as the leader of the expedition in search of the Yamatai Kingdom, with a diverse team of specialists. But shipwreck postponed the successful arrival and seemingly forgotten island is heavily populated with hostile inhabitants, cultists of Solarii Brotherhood.\r\nThe game will be graphic at times, especially after failed QTE’s during some of the survival scenes, but overall players will enjoy classic action adventure, reminiscent of the beginning of the series. This game is not a direct sequel or continuation of existing sub-series within the franchise, but a reboot, setting up Tomb Raider to represent modern gaming experience.\r\nThe game has RPG elements and has a world, which you can explore during the story campaign and after the completion. As well as multiplayer mode, where 2 teams (4 scavengers and 4 survivors) are clashing in 3 game modes while using weapons and environments from the single-player campaign.', 'https://media.rawg.io/media/games/021/021c4e21a1824d2526f925eff6324653.jpg', '2013-03-05', 2013, '["Action"]', '["PlayStation 3", "Xbox 360", "macOS", "PC"]', 0, '2026-09-16 11:06:35', '2026-09-16 05:06:35', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(7, 12020, 550, 'Left 4 Dead 2', 'left-4-dead-2', 'Cooperative survival continues with a different set of characters. New survivors are making their way through 5 campaigns with an added ability to play through the story of the first game as well, using not only expanded arsenal of 20 ranged and 10 melee weapons but improved AI Director. Your surroundings and weather will change; enemy and item placement will differ from map to map, from difficulty to difficulty. New unique special zombies, placed in the unlucky for the player spot, can end your run.\r\nHigh compatibility with community mods will allow you not only to add user-created maps but player models, enemy models, and even in-game music, which will help any player to create the unique experience on top of solid game mechanics.\r\nCompetitive multiplayer mods from arena survival to a head-on competition with another team of survivors are addictive and, in addition to the campaign, will provide you with hundreds of hours of game content.', 'https://media.rawg.io/media/games/d58/d588947d4286e7b5e0e12e1bea7d9844.jpg', '2009-11-17', 2009, '["Action", "Shooter"]', '["Xbox 360", "Linux", "PC", "macOS"]', 0, '2026-09-16 11:06:37', '2026-09-16 05:06:37', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(8, 28, 1174180, 'Red Dead Redemption 2', 'red-dead-redemption-2', 'America, 1899. The end of the wild west era has begun as lawmen hunt down the last remaining outlaw gangs. Those who will not surrender or succumb are killed. \r\n\r\nAfter a robbery goes badly wrong in the western town of Blackwater, Arthur Morgan and the Van der Linde gang are forced to flee. With federal agents and the best bounty hunters in the nation massing on their heels, the gang must rob, steal and fight their way across the rugged heartland of America in order to survive. As deepening internal divisions threaten to tear the gang apart, Arthur must make a choice between his own ideals and loyalty to the gang who raised him.\r\n\r\nFrom the creators of Grand Theft Auto V and Red Dead Redemption, Red Dead Redemption 2 is an epic tale of life in America at the dawn of the modern age.', 'https://media.rawg.io/media/games/511/5118aff5091cb3efec399c808f8c598f.jpg', '2018-10-26', 2018, '["Action"]', '["PC", "PlayStation 4", "Xbox One"]', 0, '2026-09-16 11:06:38', '2026-09-16 05:06:38', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(9, 5679, 489830, 'The Elder Scrolls V: Skyrim', 'the-elder-scrolls-v-skyrim', 'The fifth game in the series, Skyrim takes us on a journey through the coldest region of Cyrodiil. Once again player can traverse the open world RPG armed with various medieval weapons and magic, to become a hero of Nordic legends –Dovahkiin, the Dragonborn. After mandatory character creation players will have to escape not only imprisonment but a fire-breathing dragon. Something Skyrim hasn’t seen in centuries.', 'https://media.rawg.io/media/games/7cf/7cfc9220b401b7a300e409e539c9afd5.jpg', '2011-11-11', 2011, '["Action", "RPG"]', '["PlayStation 5", "PlayStation 4", "PC", "Xbox One", "Xbox Series S/X", "Nintendo Switch", "Xbox 360", "PlayStation 3"]', 1, '2026-09-16 11:06:39', '2026-09-16 05:06:39', '2026-09-16 02:48:46', '2026-09-16 08:07:29'),
	(10, 13537, 220, 'Half-Life 2', 'half-life-2', 'Gordon Freeman became the most popular nameless and voiceless protagonist in gaming history. He is painted as the most famous scientist and a hero within the world of Half-Life, and for a good reason. In the first game he saved the planet from alien invasion, this time, when the invasion is already begun, the world needs his help one more time. And you, as a player, will help this world to survive. This time Gordon arrives in City 17, ravaged and occupied by Combines, where he meets his old Black Mesa friends. \r\nWhat is different, aside from the overall design quality, is the use of Valve’s Source engine that not only expands on the fluidity of character model animations and movement but allows players to interact with a myriad of objects with the advanced and realistic (to an extent) physics. Classic Headcrab Zombies are revamped and have new variants that provide players with different threats. For a story-driven FPS, Half-Life 2 is unique in its plot delivery, and making in-game mechanics feel natural, be it platforming or driving.', 'https://media.rawg.io/media/games/b8c/b8c243eaa0fbac8115e0cdccac3f91dc.jpg', '2004-11-16', 2004, '["Action", "Shooter"]', '["PC", "macOS", "Xbox 360", "Linux", "Xbox", "Android"]', 0, '2026-09-16 11:06:40', '2026-09-16 05:06:40', '2026-09-16 02:48:46', '2026-09-16 03:06:46'),
	(11, 4062, 2028850, 'BioShock Infinite', 'bioshock-infinite', 'The third game in the series, Bioshock takes the story of the underwater confinement within the lost city of Rapture and takes it in the sky-city of Columbia. Players will follow Booker DeWitt, a private eye with a military past; as he will attempt to wipe his debts with the only skill he’s good at – finding people. Aside from obvious story and style differences, this time Bioshock protagonist has a personality, character, and voice, no longer the protagonist is a silent man, trying to survive.\r\nOpen and bright level design of Columbia shows industrial colonial America in a seemingly endless carnival. But Bioshock is not famous for its visuals, but for its story.  Mystery and creative vision of Irrational Games invite players to uncover the secrets of Columbia’s leader - Zachary Comstock and save Elizabeth, the girl, that’s been locked up in the flying city since her birth.\r\nUnique weapons and mechanics of Vigor will make encounters different, helping players to adjust to the new found mobility and hook shot, making fights fast-paced and imaginative.', 'https://media.rawg.io/media/games/fc1/fc1307a2774506b5bd65d7e8424664a7.jpg', '2013-03-26', 2013, '["Action", "Shooter"]', '["PlayStation 4", "Xbox 360", "Nintendo Switch", "Linux", "PC", "PlayStation 3", "Xbox One"]', 0, '2026-09-16 11:06:45', '2026-09-16 05:06:45', '2026-09-16 02:48:46', '2026-09-16 03:08:50'),
	(12, 802, 49520, 'Borderlands 2', 'borderlands-2', 'Sequel to the 4-player cooperative FPS RPG Borderlands, where the new team of Vault Hunters arrives on the infamous planet Pandora in order to get the riches, hidden inside the Vault, and help to free the planet from the Handsome Jack, President of Hyperion. Clear out the endless waves and groups and marauders with various weapon types and character abilities.\r\nUnlike the first game, Borderlands 2 provided DLC not only expanding the world of Pandora with stand-alone story campaigns but adding 2 more characters. Now the main cast consists of Gunzerker Salvador(dual-wields guns at command), Siren Maya (holds and paralyzes the enemy), Commando Axton (summons turrets) and Zer0 the Assasin (invisible sniper ninja). But with the DLC players can try out summoning giant flying robots with Gaige the Mechromancer and Krieg the Psycho. \r\nMost of the game charm and popularity of Borderlands 2 comes from the supporting cast and the personalities of the NPC, making this fast-paced shooter with optional cover stand out.', 'https://media.rawg.io/media/games/49c/49c3dfa4ce2f6f140cc4825868e858cb.jpg', '2012-09-18', 2012, '["Action", "Shooter", "RPG"]', '["PlayStation 3", "macOS", "PC", "Android", "Linux", "PS Vita", "Xbox 360"]', 0, '2026-09-16 11:09:03', '2026-09-16 05:09:03', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(13, 3439, 532210, 'Life is Strange', 'life-is-strange-episode-1-2', 'Interactive storytelling and plot-heavy games gained popularity, and “Life is Strange” arrived as teen mystery adventure. The plot will go through the life of Maxine, a teenager in possession of curious power, allowing her to stop and rewind time, in order to manipulate her surroundings. Max, after the reunion with her friend Chloe, is on the path to uncovering the secrets of Arcadia Bay. Players will have to deal with puzzle solving through the fetch quests, in order to change the world around them. \nThe game puts players in situations, where they’re forced to make a moral choice, going through the decision which may have short-term or long-term consequences. Every choice made by the player will trigger the butterfly effect, surrounding the first playthrough of the game with a lot of emotional struggle, thoughtfully crafted by the developers at Dontnod Entertainment. Life is Strange is third person adventure game, where players might seem just as an observer of the stories, unfolding in front of them.', 'https://media.rawg.io/media/games/562/562553814dd54e001a541e4ee83a591c.jpg', '2015-01-29', 2015, '["Adventure"]', '["iOS", "PC", "Linux", "PlayStation 3", "macOS", "Xbox 360", "Android", "PlayStation 4", "Xbox One"]', 0, '2026-09-16 11:09:04', '2026-09-16 05:09:04', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(14, 4286, 8870, 'BioShock', 'bioshock', 'FPS with RPG elements, Bioshock invites players to experience horrors of underwater isolation in the city of Rapture, the failed project of the better future. After surviving the plane crash, the protagonist has only one way to go – to the giant lighthouse that opens a way to the underwater utopia. Players will have to unravel the complicated history of Rapture, relying only on themselves, their guns and Plasmids, a mystical substance, that allows it’s user to obtain near magical abilities.\r\nThe atmosphere of isolation and threat is conveyed through the environmental sounds, subtle electrical buzzing and audio logs, telling the story of societal decay and despair. Players will shape the story, making moral choices along their way, saving Little Sisters or extracting ADAM, the mystical fuel for your abilities. While exploring the underwater city, players will complete missions for the last sane inhabitants of Rapture, while fending off the less fortunate ones.', 'https://media.rawg.io/media/games/bc0/bc06a29ceac58652b684deefe7d56099.jpg', '2007-08-21', 2007, '["Action", "Shooter"]', '["PlayStation 3", "macOS", "PC", "Xbox 360"]', 0, '2026-09-16 11:09:05', '2026-09-16 05:09:05', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(15, 58175, NULL, 'God of War (2018)', 'god-of-war-2', 'It is a new beginning for Kratos. Living as a man outside the shadow of the gods, he ventures into the brutal Norse wilds with his son Atreus, fighting to fulfill a deeply personal quest. \r\n\r\nHis vengeance against the Gods of Olympus years behind him, Kratos now lives as a man in the realm of Norse Gods and monsters. It is in this harsh, unforgiving world that he must fight to survive… And teach his son to do the same. This startling reimagining of God of War deconstructs the core elements that defined the series—satisfying combat; breathtaking scale; and a powerful narrative—and fuses them anew. \r\n\r\nKratos is a father again. As mentor and protector to Atreus, a son determined to earn his respect, he is forced to deal with and control the rage that has long defined him while out in a very dangerous world with his son. \r\n\r\nFrom the marble and columns of ornate Olympus to the gritty forests, mountains, and caves of Pre-Viking Norse lore, this is a distinctly new realm with its own pantheon of creatures, monsters, and gods. With an added emphasis on discovery and exploration, the world will draw players in to explore every inch of God of War’s breathtakingly threatening landscape—by far the largest in the franchise. \r\n\r\nWith an over the shoulder free camera that brings the player closer to the action than ever before, fights in God of War mirror the pantheon of Norse creatures Kratos will face: grand, gritty, and grueling. A new main weapon and new abilities retain the defining spirit of God of War while presenting a vision of violent conflict that forges new ground in the genre', 'https://media.rawg.io/media/games/4be/4be6a6ad0364751a96229c56bf69be59.jpg', '2018-04-20', 2018, '["Action"]', '["PC", "PlayStation 4"]', 0, '2026-09-16 11:09:06', NULL, '2026-09-16 02:48:46', '2026-09-16 03:09:06'),
	(16, 32, 1085660, 'Destiny 2', 'destiny-2', 'Destiny 2 is an online multiplayer first-person shooter. You take on the role of a Guardian that needs to protect the last city on Earth from alien invaders. The game follows its predecessor, Destiny. The goal of the game is to return the Light that was stolen from the Guardians by the aliens.\nDestiny 2 features two main activity types: player versus environment and player versus player. PvE is focused on exploration, story missions interaction with NPCs and side quests. PvP features 4v4 team matches in different modes. The game also allows taking part in group missions, such as three-player strikes and six-player raids.\nDestiny 2 has a strong RPG aspect that includes character customization and development. There are three classes in the game - Warlock, Hunter, and Titan; they provide different playstyles depending on their specialization and unique abilities. To develop the character you can gain experience points completing the story and side missions.', 'https://media.rawg.io/media/games/34b/34b1f1850a1c06fd971bc6ab3ac0ce0e.jpg', '2017-09-06', 2017, '["Action", "Shooter"]', '["PlayStation 4", "Xbox One", "PC", "Web", "Xbox Series S/X", "PlayStation 5"]', 0, '2026-09-16 11:09:07', '2026-09-16 05:09:07', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(17, 3070, 377160, 'Fallout 4', 'fallout-4', 'The fourth game in the post-apocalyptic action RPG series from Bethesda studious brings players back to the retro-future. After customizing the facial features of the character, players will be admitted to the Vault 111 with their family, and tricked into entering the cryogenic capsule. After the rude awakening after the unknown amount of time has passed, the child is separated from the parents and the loving partner is killed in front of them – the main quest is settled. Now there’s only the giant open world to explore. Fallout 4 introduces the mechanics of settlement building, where players can build their own little town. Gathering material for crafting and building brings more “survival” elements into the old formula. Within their own settlements, players will be able to build all needed utilities, from storage spaces to power armor stations. Visual upgrade from the previous game brings life to what used to be brown wastelands, now filled with details and color.', 'https://media.rawg.io/media/games/d82/d82990b9c67ba0d2d09d4e6fa88885a7.jpg', '2015-11-09', 2015, '["Action", "RPG"]', '["PlayStation 4", "PC", "PlayStation 5", "Xbox One"]', 1, '2026-09-16 11:09:08', '2026-09-16 05:09:08', '2026-09-16 02:48:46', '2026-09-16 08:07:29'),
	(18, 1030, 2214822, 'Limbo', 'limbo', 'This popular 2D puzzle-platformer creates the atmosphere of isolation, where the player alone can guide the nameless protagonist to his destination. Hostile environments and one-hit deaths may seem difficult, but the game implements a fair amount of checkpoints. The monochrome color palette showcases cartoony proportions of every living thing while making lack of details threatening. Limbo shows you exactly what you encounter, but never how it looks.\n\nLimbo uses the atmosphere and sound design of the horror genre while avoiding tropes of the modern horror games. The overarching theme and unique style compensated for the rather short game with an abrupt ending, making Limbo one of the most impactful games for the genre.\n\nThe simple controls and easy-to-pick-up mechanics help to make a clear distinction, which part of the stage players can interact with, and which part can lead to the quick death. Even though the game is in black and white, this separation is intuitive and natural, so the player would know exactly where to go or what to do.', 'https://media.rawg.io/media/games/942/9424d6bb763dc38d9378b488603c87fa.jpg', '2010-07-21', 2010, '["Action", "Adventure", "Indie", "Puzzle", "Platformer"]', '["PC", "Android", "PS Vita", "PlayStation 4", "PlayStation 3", "Xbox 360", "Linux", "macOS", "iOS", "Xbox One", "Nintendo Switch"]', 0, '2026-09-16 11:09:09', '2026-09-16 05:09:09', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(19, 3939, 218620, 'PAYDAY 2', 'payday-2', 'The gang is back, and they have bigger and better plans. Objective based cooperative FPS became more complicated. The classic group of Hoxton, Dallas, Chains and Wolf got reinforcement, and now Payday Gang consists of 21 heisters, some of which are based on movie characters or even Youtubers. Players will be able to customize their own private arsenal, their masks, and skills, to complete the missions in their own way, be it stealthy sneak-in or full frontal assault. After completing missions, players will receive EXP points, money and a chance to get a special item that can be a gun modification, mask or a safe containing weapon skins.\r\nPayday 2 is a multiplayer game, meaning, that even during offline missions players will be followed by AI characters, whose loadouts, masks and perks can be customized as well. This game has been supported by the developers for many years, and amount of DLC speaks plenty of their dedication to the player base.', 'https://media.rawg.io/media/games/73e/73eecb8909e0c39fb246f457b5d6cbbe.jpg', '2013-08-13', 2013, '["Action", "Shooter"]', '["Linux", "PC", "Xbox One"]', 0, '2026-09-16 11:09:10', '2026-09-16 05:09:10', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(20, 2454, NULL, 'DOOM (2016)', 'doom', 'Return of the classic FPS, Doom (2016) acts as a reboot of the series and brings back the Doomslayer, protagonist of the original Doom games. In order to solve the energy crisis, humanity learned to harvest the energy from Hell, and when something went wrong and a demon invasion has started, it’s up to the player to control the Doomslayer and destroy the evil.\n\nDoom is a fast-paced game that restores the concept of instant health packs and leaves the player against armies of Hell with no cover, no health regeneration, or help from anyone. After damaging monsters enough, they will start glowing, which will allow players to perform glory kills to restore some health. While exploring the levels, players will come across secrets, collectible items, or upgrade points for the weapons and armor. The single-player campaign silent protagonist has a noticeable personality. He gets visibly annoyed and angry in his actions during expository cutscenes and forces his way through the game. Multiplayer maps gather players in Deathmatch/”king-of-the-hill” type game modes, with all the weapons from the single-player campaign.', 'https://media.rawg.io/media/games/587/587588c64afbff80e6f444eb2e46f9da.jpg', '2016-05-12', 2016, '["Action", "Shooter"]', '["PC", "PlayStation 4", "Nintendo Switch", "Xbox One"]', 0, '2026-09-16 11:09:11', NULL, '2026-09-16 02:48:46', '2026-09-16 03:09:11'),
	(21, 41494, 1091500, 'Cyberpunk 2077', 'cyberpunk-2077', 'Cyberpunk 2077 is a science fiction game loosely based on the role-playing game Cyberpunk 2020.\r\n\r\n###Setting\r\nThe game is set in the year 2077 in a fictional futuristic metropolis Night City in California. In the world of the game, there are developed cybernetic augmentations that enhance people\'s strength, agility, and memory. The city is governed by corporations. Many jobs are taken over by the robots, leaving a lot of people poor and homeless. Night City has a roaring underworld, with black markets, underground surgeons, drug dealers, and street gangs abound.\r\n\r\n###Characters\r\nThe main protagonist is fully customizable, including his or her sex and appearance, and goes by the nickname V. He or she is an underground mercenary who does “dirty business” for the various contractors. An NPC companion named Jackie joins the protagonist early at the game, and various other companions may join the player on certain missions as the plot demands. However, the game has no parties and no companion system.\r\n\r\n###Gameplay\r\nThe player controls V from the first person view, with the third-person view used for cutscenes only. The protagonist can travel across the city on feet or using various vehicles, in a manner some observers compared to GTA series. There are many options for the character customization, including three character classes, and a variety of augmentations V can install to enhance his or her abilities.', 'https://media.rawg.io/media/games/26d/26d4437715bee60138dab4a7c8c59c92.jpg', '2020-12-10', 2020, '["Action", "Shooter", "RPG"]', '["Nintendo Switch", "PlayStation 4", "PC", "Xbox Series S/X", "PlayStation 5", "Xbox One"]', 0, '2026-09-16 11:09:12', '2026-09-16 05:09:12', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(22, 11859, 440, 'Team Fortress 2', 'team-fortress-2', 'TF2 is an objective based arena shooter with unique characters, representing different classes, acting as a staple of casual and competitive gaming for Steam. Dozens of different maps and game modes are trying to keep this game alive, after all the years it was available. Each character has a vast arsenal that can be accessed through completing in-game achievements, randomly receiving them from loot-boxes within the game, crafting them or just buying and trading items on the Steam Market. \r\nFor players, that\'s not into the direct clash with players from the enemy team, Team Fortress 2 introduced a PvE mode, which is wave defense from the mirrored robotic opponents that have qualities of some of the playable classes. \r\nEvery update and introduction, made over years, provided a lot of entertainment In the form of comic books an short animated videos, creating and explaining a story behind endless clashes for resources, briefcases or pure domination.', 'https://media.rawg.io/media/games/46d/46d98e6910fbc0706e2948a7cc9b10c5.jpg', '2007-10-10', 2007, '["Action", "Shooter"]', '["Linux", "macOS", "PC"]', 0, '2026-09-16 11:09:13', '2026-09-16 05:09:13', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(23, 422, 105600, 'Terraria', 'terraria', 'Terraria is a 2D action adventure sandbox game, where players create a character and gather resources in order to gradually craft stronger weapons and armor. Players create randomly generated maps that contain different locations within it, and by gathering specific resources and triggering special events, players will fight one of the many in-game bosses. Created characters can be played on different maps.\r\nThe game introduces hundreds of unique items that can be found across the entirety of the map, some of which may not even be encountered. \r\nTerraria have many different Biomes and areas with distinct visuals, containing resources and enemies unique to this biome. After gathering materials, players can craft furniture, and build settlements and houses, since after completing events or finding specific items NPCs will start to arrive, and will require player’s protection. Terraria can be played on three difficulties and has a large modding community.', 'https://media.rawg.io/media/games/f46/f466571d536f2e3ea9e815ad17177501.jpg', '2011-05-16', 2011, '["Action", "Indie", "Platformer"]', '["Xbox 360", "Wii U", "Nintendo 3DS", "Xbox One", "PlayStation 4", "iOS", "PC", "macOS", "Linux", "Nintendo Switch", "PlayStation 3", "PS Vita", "Android"]', 0, '2026-09-16 11:09:19', '2026-09-16 05:09:19', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(24, 4459, 12210, 'Grand Theft Auto IV', 'grand-theft-auto-iv', 'Every crime story is a story of a search for success. The player will become Niko Bellic, immigrant arriving at the Liberty City to reunite with his cousin Roman and find the man that betrayed him and his army unit fifteen years prior to the events of the game. While protecting his cousin, Niko has to deal with loan sharks, Russian mobsters, and other gangs. After the third game, GTA brought more realism to the player, in order to make the city and its people look more believable. Street vendors on every corner will sell food that replenishes health, bars with playable dart boards, bowling alleys and even comedy clubs and movie theatres. Open world will allow players not only hang out with important NPC in order to receive bonuses and unlocks but taking girls on the dates as well, to help Niko settle. Multiplayer mode allows up to 32 players to explore the copy of the single-player city and initiate multiplayer activities, like races or Deathmatches.', 'https://media.rawg.io/media/games/4a0/4a0a1316102366260e6f38fd2a9cfdce.jpg', '2008-04-29', 2008, '["Action", "Adventure"]', '["Xbox 360", "PC", "PlayStation 3", "Xbox One"]', 0, '2026-09-16 11:09:21', '2026-09-16 05:09:21', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(25, 10213, 570, 'Dota 2', 'dota-2', 'What used to be an unofficial modded map for the Warcraft 3, ended up being the most budgeted cybersport discipline, gathering millions of people to watch annual international championships.\nMOBA genre started with the DOTA, Defense of the Ancients, which can be efficiently described as 5 vs 5 top-down action strategy game, during which players are tasked to destroy the enemy core while protecting their own.\nPlayers can pick out of the roster of 112 heroes and battle on the single map while taking advantage of field vision, resources and item build that can either make heroes stronger or disable the enemy. DOTA 2 is still active, and receives updates weekly, reshaping metas and refreshing game balance, if by any chance some heroes became unreasonably strong. Each hero has not only a unique set of abilities but is fully customizable, through getting items for heroes after matches of through the trade. Not only heroes but terrain, couriers, that deliver items for you and even match announcers, that can be voiced by heroes, professional casters of just memorable characters from other forms of media.', 'https://media.rawg.io/media/games/6fc/6fcf4cd3b17c288821388e6085bb0fc9.jpg', '2013-07-09', 2013, '["Action", "Massively Multiplayer"]', '["Linux", "macOS", "PC"]', 0, '2026-09-16 11:09:22', '2026-09-16 05:09:22', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(26, 766, 230410, 'Warframe', 'warframe', 'Warframe is an online free-to-play cooperative third-person looter shooter. In the far future the Orokin had absolute control over the solar system but have since disappeared, now the militaristic Grineer, the money-worshipping Corpus, and the Infested fight for what they left behind. You are a Tenno - a master of gun and blade and user of the Warframes, it is up to you to bring back balance to the system from within, while also fighting a new threat from without: the Sentients.\r\nOver 40 unique Warframes to build, hundreds of guns and melee weapons to utilize, and various pet companions to help you along the way - all of which can be crafted for free and enhanced by an in-depth modding system.\r\nWith constant updates by Digital Extremes, the game now has over six years of updates including new open-world landscapes (Plains of Eidolon-2017, Orb Vallis-2018) and cinematic story expansions (The Second Dream-2015, The War Within-2016, The The Sacrifice-2018) with more content being added every year.', 'https://media.rawg.io/media/games/f87/f87457e8347484033cb34cde6101d08d.jpg', '2013-03-25', 2013, '["Action", "Shooter", "RPG", "Massively Multiplayer"]', '["iOS", "Xbox Series S/X", "PlayStation 5", "PlayStation 4", "Xbox One", "Nintendo Switch", "PC"]', 0, '2026-09-16 11:09:24', '2026-09-16 05:09:24', '2026-09-16 02:48:46', '2026-09-16 03:09:44'),
	(27, 3272, NULL, 'Rocket League', 'rocket-league', 'Highly competitive soccer game with rocket-cars is the most comprehensive way to describe this game. Technically a sequel to Psyonix’ previous game - Supersonic Acrobatic Rocket-Powered Battle-Cars; Rocket League successfully became a standalone sensation, that can be enjoyed by anyone. Easy to learn, hard to master game mechanics are perfect for the tight controls. Players are invited to maneuver the different fields within several game modes, from arcade to ranked game either 1v1, or in 2v2 and 3v3 teams. Using boosters will not only speed up the car but will allow the car to propel itself into the air.\r\nRocket League provides several levels of customization, where not only the color of your car can be adjusted, but the colors and form of the booster flame, different hats, and little flags. Or players can pick a completely different car. Collaboration with different franchises brought not only original transport but some famous cars, including Batmobile or Delorian from Back to the Future.', 'https://media.rawg.io/media/games/8cc/8cce7c0e99dcc43d66c8efd42f9d03e3.jpg', '2015-07-07', 2015, '["Sports", "Racing", "Indie"]', '["Nintendo Switch", "macOS", "PC", "Linux", "Xbox One", "PlayStation 4"]', 0, '2026-09-16 11:09:24', NULL, '2026-09-16 02:48:46', '2026-09-16 03:09:24'),
	(28, 278, 2561580, 'Horizon Zero Dawn', 'horizon-zero-dawn', 'Horizon Zero Dawn is an experiment. A very impressive experiment that actually succeeded. \r\nHaving a very curious mix of cyberpunk and prehistorical styles and esthetic, the game provides us with quite a unique experience. We need to arm ourselves with arrows and a bow, with a spear or any other prehistorical-ish weapon in order to defeat out enemies - dinosaur-mechanisms that are spread around the world. If that wasn\'t enough, Aloy our main protagonist can control an AI named GAIA. What we\'re having here is an exciting connection with "very old times" and "near future", even though the game is set up in the 31st century. \r\nBeing an outcast with her father Rost, Aloy must restore her position in the tribe and save the world by stopping the Eclipse, a cult that wants to rule the world. Join her on that journey, exploring the world and people that live in such hard surroundings.', 'https://media.rawg.io/media/games/b7d/b7d3f1715fa8381a4e780173a197a615.jpg', '2017-02-28', 2017, '["Action", "RPG"]', '["PC", "PlayStation 4"]', 1, '2026-09-16 11:09:31', '2026-09-16 05:09:31', '2026-09-16 02:48:46', '2026-09-16 08:07:29'),
	(29, 29028, 286690, 'Metro 2033', 'metro-2033', 'Not all post-apocalyptic stories begin in the burned wastelands, this time nuclear and chemical locked up survivors in the Moscow Subway, and player will take the place of Artyom, one of the survivors from the VDNKh, adoptive son of the station commander, and taking upon himself the task to deliver information about the Dark Ones to the Polis, the capital of subway, after the special operative from Spartans named Hunter went missing, after he ventured to gather information on the Hive – living space of the Dark Ones.\r\nDark tunnels of broken subway create a claustrophobic atmosphere, where good and bad people alike are forced to bond. Closely following original book, Metro 2033 introducing bullets as currency. Players can exchange one type of bullets for another one, but it’s still ammo and will be wasted with inaccurate aim. It’s a first person shooter that will allow players not only see how broken apart can society become but to explore such society and ruins of the city above the underground settlement. Various monsters and mutants are not the only threat to the players, but humans as well. FPS with some stealth sections, Metro 2033 will show you every historical enemy type: bandits, Communists, and Nazis.', 'https://media.rawg.io/media/games/120/1201a40e4364557b124392ee50317b99.jpg', '2010-03-16', 2010, '["Action", "Shooter"]', '["PC", "Xbox 360"]', 0, '2026-09-16 11:09:32', '2026-09-16 05:09:32', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(31, 3287, 208650, 'Batman: Arkham Knight', 'batman-arkham-knight', 'Batman: Arkham Knight is the final instalment for the Arkham series by now. Joining forces with Bruce Wayne for the last time, we have to oppose Scarecrow and other iconic villains such as The Riddler, Harleen Quinzel a.k.a. Harley Quinn, Penguin and others.\n\nThe story continued after events in Arkham City when Joker died due to infection in his blood. Now, Scarecrow tries to release a new fear toxin, meanwhile new mysterious Arkham Knight plots against Batman as well. Still having consequences after being poisoned by the Joker and seeing visions with him, Bruce has to prevail the death of Gotham City.\n\nThe gameplay mechanics stays the same to the Arkham series. Melee combat system, use of the detective skills to find clues and gadgets still play a major role in Batman\'s fight against evil. Although now you can travel around not only by your grappling hook but a legendary Batmobile as well. Iconic voices of the characters, Kevin Conroy and Mark Hammil once again return to give their voices for the last game in Arkham series.', 'https://media.rawg.io/media/games/310/3106b0e012271c5ffb16497b070be739.jpg', '2015-06-23', 2015, '["Action"]', '["PC", "Nintendo Switch", "Xbox One", "PlayStation 4"]', 0, '2026-09-16 11:09:35', '2026-09-16 05:09:35', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(32, 416, 1547000, 'Grand Theft Auto: San Andreas', 'grand-theft-auto-san-andreas', 'Grand Theft Auto - San Andreas is the seventh entry in the series in the GTA franchise, but only second big title after GTA - Vice City. Setting up in fictional state San Andreas, you follow the story of CJ, a member of one of the multiple gangs in the city. CJ\'s family is being attacked in drive shooting which resulted in the death of CJ\'s mother, so he returns to home from Liberty City. Meeting the rest of the family at his mom\'s funeral, he decides to rebuild the gang and gain control of the state.\r\n\r\nThe game makes a brilliant connection with missions and open world actions that you are able to do around the cities. You can steal cars, buy guns, hunt for collectables and do some side quests, while different characters give you specific missions in order to push the plot forward. Streets are filled with people as well as plenty of vehicles to steal. Fictional brands of cars, tanks, bikes are available to be stolen from any place around the city. Armoury contains pistols, rifles, hand-machine guns or a rocket launcher as well as melee weapons giving player freedom in anything he\'s doing in GTA.', 'https://media.rawg.io/media/games/960/960b601d9541cec776c5fa42a00bf6c4.jpg', '2004-10-26', 2004, '["Action"]', '["macOS", "PC", "iOS", "Xbox", "Android", "PlayStation 4", "PlayStation 3", "PlayStation 2", "Xbox 360", "Xbox One"]', 0, '2026-09-16 11:09:36', '2026-09-16 05:09:36', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(33, 3192, 287700, 'Metal Gear Solid V: The Phantom Pain', 'metal-gear-solid-v-the-phantom-pain', 'Metal Gear Solid 5 continues the story of MGS: Peace Walker and MGS V: Ground Zeroes. Snake seeks revenge for the attack on the MSF group 9 years ago, that placed Big Boss into a coma. After the failed assassination attempt, Big Boss takes the code name Venom Snake, delving back into the world of superhumans and espionage.\r\nA large-scale story that includes 5 hours of cinematic cutscenes compliments open world exploration with hundreds of audio logs and side missions, forming the atmosphere of military drama with sci-fi elements. MGS5: Phantom Pain has an advanced AI system that will allow enemy soldiers constantly call for reinforcements if they see that something is wrong, forcing players to take down communications and fight or retreat and try again. \r\nPlayers will manage the base by gathering and managing staff, weaponry, and resources, in order to upgrade their personal arsenal and companions.', 'https://media.rawg.io/media/games/490/49016e06ae2103881ff6373248843069.jpg', '2015-09-01', 2015, '["Action", "Shooter"]', '["PlayStation 4", "PC", "Xbox One", "PlayStation 3", "Xbox 360"]', 0, '2026-09-16 11:09:37', '2026-09-16 05:09:37', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(34, 16944, 20920, 'The Witcher 2: Assassins of Kings Enhanced Edition', 'the-witcher-2-assassins-of-kings-enhanced-edition', 'The player is Geralt of Rivia, infamous monster slayer. In the second game of the series, titular witcher is involved in the inner conflicts of Temeria, where he stopped the rebellion and was hired as a bodyguard of Temerian King Foltest. Eventually, Foltest was assassinated by a witcher-like assassin, and the only person fitting the description was Geralt. \r\nThe game combat system was reworked, in order to add traps and ranged throwing weapon, giving players more control over the course of the battle. It’s still a third person action RPG, and the player can upgrade and improve general abilities, swordsmanship, alchemy, and magic. \r\nThe enhanced edition includes additional hours of content, new cinematics, the original soundtrack, game manual and quest handbook, among other things. The new tutorial allows players to spend more time to master new game mechanics and see for themselves visual improvements to the core game.', 'https://media.rawg.io/media/games/6cd/6cd653e0aaef5ff8bbd295bf4bcb12eb.jpg', '2012-04-16', 2012, '["RPG"]', '["macOS", "PC", "Xbox 360"]', 0, '2026-09-16 11:09:38', '2026-09-16 05:09:38', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(35, 290856, 1172470, 'Apex Legends', 'apex-legends', 'Conquer with character in Apex Legends, a free-to-play* Battle Royale shooter where legendary characters with powerful abilities team up to battle for fame and fortune on the fringes of the Frontier. Master an ever-growing roster of diverse legends, deep tactical squad play, and bold new innovations that level-up the Battle Royale experience—all within a rugged world where anything goes. Welcome to the next evolution of Battle Royale.\n\nCharacters you can play as: Caustic, Bangalore, Bloodhound, Crypto, Gibraltar, Lifeline, Loba, Mirage, Octane, Pathfinder, Rampart, Revenant.', 'https://media.rawg.io/media/games/737/737ea5662211d2e0bbd6f5989189e4f1.jpg', '2019-02-04', 2019, '["Action", "Shooter"]', '["PlayStation 4", "Nintendo Switch", "macOS", "PC", "Xbox One"]', 0, '2026-09-16 11:09:39', '2026-09-16 05:09:39', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(36, 9767, 367520, 'Hollow Knight', 'hollow-knight', 'Hollow Knight is a Metroidvania-type game developed by an indie studio named Team Cherry.\r\n\r\nMost of the game\'s story is told through the in-world items, tablets, and thoughts of other characters. Many plot aspects are told to the player indirectly or through the secret areas that provide a bit of lore in addition to an upgrade. At the beginning of the game, the player visits a town of Dirtmouth. A town built above the ruins of Hallownest. The players descend down into the ruins to find some answers to his questions.\r\n\r\nThe game revolves mainly around the exploration of the in-game world, which requires the players to have some platforming skills. The players have to find secrets that are scattered around the level and battle their enemies. There is a certain degree of backtracking in the game as some areas are locked until the player defeats a certain boss or picks up a specific item. Each area changes as the plot advances so it may be surprising to come back in a certain area. \r\n\r\nThe Protagonist uses a nail which serves as a replacement for a sword. Players can attack in four directions. The nail is upgradable.', 'https://media.rawg.io/media/games/4cf/4cfc6b7f1850590a4634b08bfab308ab.jpg', '2017-02-23', 2017, '["Action", "Indie", "Platformer"]', '["PlayStation 4", "Linux", "macOS", "PC", "Nintendo Switch", "Xbox One"]', 0, '2026-09-16 11:09:40', '2026-09-16 05:09:40', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(37, 17822, 20900, 'The Witcher: Enhanced Edition Director\'s Cut', 'the-witcher-enhanced-edition-directors-cut', 'The Witcher is the very first instalment of the series that follows the story of Geralt from Rivia. Being found unconscious on the battlefield he must retrieve his memory and help the emperor\'s daughter, Adda to stop her from turning in to a feral monster. Facing the biggest enemy, Salamander, Geralt must also help all the fractions around the world to find peace between each other.\n\nThe fighting system is very flexible. Choosing from three different styles, you can adapt Geralt for any kind of a combat situation. Fast style of fighting gives you an opportunity to strike your opponents with your speed. The strong style focuses itself on destroying your enemies with powerful attacks, while sweeping style is very good when facing a number of foes. You can also craft some potions to gain important benefits such as seeing in the dark or having a larger amount HP. Plot style is unique as well. The game never gives a precise definition of evil, which leads the player to convenient situations where the choice is quite bad anyway. Enhanced edition improves every aspect of the game as graphics and the productivity of it, while Director\'s Cut does the same without censorship for North America\'s version.', 'https://media.rawg.io/media/games/ee3/ee3e10193aafc3230ba1cae426967d10.jpg', '2008-09-16', 2008, '["Action", "RPG"]', '["PC", "macOS"]', 0, '2026-09-16 11:09:41', '2026-09-16 05:09:41', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(38, 11973, 241930, 'Middle-earth: Shadow of Mordor', 'shadow-of-mordor', 'Lord of the rings franchise brought a new title to the collection, an open world action-adventure game, that follows Talion, Gondor captain, that survived the sacrifice that was meant to bring the Elf Lord Celebrimbor as a wraith. Losing his wife and his son, Talion is merged with Celebrimor, escaping death.  Players will have to gain EXP in order to upgrade abilities through completing various missions and defeating Uruk warlords. Some missions might require special conditions for the greater reward.\r\nShadow of Mordor implemented the Nemesis System. It tracks the progress of every special Uruk warrior. Each special Uruk has a set of strengths and weaknesses, and players can assassinate higher ranked officers in order to promote easy to defeat Uruk to defeat them at a higher rank, weakening the Sauron’s army. This planning allows players to adapt, and use mechanics of stealth kills, ranged combat, wraith skills and head-on melee more effective.', 'https://media.rawg.io/media/games/d1a/d1a2e99ade53494c6330a0ed945fe823.jpg', '2014-09-30', 2014, '["Action", "RPG"]', '["Linux", "Xbox One", "Xbox 360", "PlayStation 3", "PlayStation 4", "macOS", "PC"]', 0, '2026-09-16 11:09:42', '2026-09-16 05:09:42', '2026-09-16 02:48:46', '2026-09-16 03:09:45'),
	(39, 23027, NULL, 'The Walking Dead: Season 1', 'the-walking-dead', 'The Walking Dead is a five-part game series set in the same universe as Robert Kirkman’s award-winning comic book series. Play as Lee Everett, a convicted criminal, who has been given a second chance at life in a world devastated by the undead. With corpses returning to life and survivors stopping at nothing to maintain their own safety, protecting an orphaned girl named Clementine may offer him redemption in a world gone to hell.\r\nA continuing story of adventure horror spanning across 5 episodes:\r\n\r\nEpisode 1 – A New Day (Available Now)\r\nEpisode 2 – Starved for Help (Available Now)\r\n\r\nEpisode 3 – Long Road Ahead (Available Now)\r\nEpisode 4 – Around Every Corner (Available Now)\r\nEpisode 5 – No Time Left (Available Now)\r\nAll five episodes are now available immediately upon purchasing Season 1. Based on Robert Kirkman’s Eisner-Award winning comic book series, The Walking Dead allows gamers to experience the true horror of the zombie apocalypse\r\nA tailored game experience – Live with the profound and lasting consequences of the decisions that you make in each episode. Your actions and choices will affect how your story plays out across the entire series.\r\nExperience events, meet people and visit locations that foreshadow the story of Deputy Sheriff Rick Grimes\r\nMeet Glenn before he heads to Atlanta, explore Hershel’s farm before Rick and his group of survivors arrive and before the barn becomes a notorious location in Walking Dead lore\r\nYou’ll be forced to make decisions that are not only difficult, but that will require you to make an almost immediate choice. There’s no time to ponder when the undead are pounding the door down!\r\nFeatures meaningful decision-making, exploration, problem solving and a constant fight for survival in a world overrun by the undead\r\nArtwork inspired by the original comic books', 'https://media.rawg.io/media/games/8d6/8d69eb6c32ed6acfd75f82d532144993.jpg', '2012-04-23', 2012, '["Action", "Adventure"]', '["Android", "PS Vita", "macOS", "PC", "iOS", "PlayStation 4", "PlayStation 3", "Xbox 360", "Nintendo Switch", "Xbox One"]', 0, '2026-09-16 11:09:43', NULL, '2026-09-16 02:48:47', '2026-09-16 03:09:43'),
	(40, 41, 424840, 'Little Nightmares', 'little-nightmares', 'Heavily inspired by Limbo and Inside, Little Nightmares are telling a story of another lost child. Six is a starving little girl in a yellow raincoat, which is trapped in a mysterious vessel named the Maw. Players are taking control of Six’s movement, in order to help her escape the ship and dangerous inhabitants, that’s been kidnaping and preparing children to be served as a feast for the Guests. \nThe control scheme is not including any combat moves, leaving players defenseless against any threat. Six can run, crawl, climb, push or pull, and in rare cases carry an object she can throw to stagger an enemy or solve a puzzle. The game gives players the ability to carry a lighted match at any time, inviting players to explore and search for the collectible statues. \nLittle Nightmares have 3 DLC levels, expanding the game beyond the perspective of Six, where the Runaway Kid, a young boy, who is trying to catch up to Six and having his own adventure, going through the Maw in the extra chapters, named “The Depths”, “The Hideaway” and “The Residence.”', 'https://media.rawg.io/media/games/8a0/8a02f84a5916ede2f923b88d5f8217ba.jpg', '2017-04-27', 2017, '["Action", "Adventure", "Platformer"]', '["iOS", "PlayStation 4", "PC", "Xbox One", "Nintendo Switch"]', 0, '2026-09-16 11:09:44', '2026-09-16 05:09:44', '2026-09-16 02:48:47', '2026-09-16 03:09:45');
