INSERT IGNORE INTO `game_requirements` (`requirement_id`, `game_id`, `requirement_type`, `operating_system`, `cpu_text`, `gpu_text`, `ram_text`, `storage_text`, `ram_capacity_gb`, `ram_speed_mhz`, `raw_html`, `source`, `synced_at`, `created_at`, `updated_at`) VALUES
	(1, 1, 'minimum', 'Windows 10 (latest service pack)', 'Intel® Core™ i7-4770 | AMD FX™-9590', 'NVIDIA GeForce® GTX 1630 (4GB VRAM) | AMD Radeon™ RX 6400 (4GB VRAM)', '8 GB RAM', '105 GB available space', 8, NULL, '<strong>Minimum:</strong><br><ul class="bb_ul"><li>Requires a 64-bit processor and operating system<br></li><li><strong>OS:</strong> Windows 10 (latest service pack)<br></li><li><strong>Processor:</strong> Intel® Core™ i7-4770 | AMD FX™-9590<br></li><li><strong>Memory:</strong> 8 GB RAM<br></li><li><strong>Graphics:</strong> NVIDIA GeForce® GTX 1630 (4GB VRAM) | AMD Radeon™ RX 6400 (4GB VRAM)<br></li><li><strong>Storage:</strong> 105 GB available space<br></li><li><strong>Sound Card:</strong> DirectX 10 Compatible<br></li><li><strong>Additional Notes:</strong> SSD Required  |  Over time downloadable content and programming changes will change the system requirements for this game. Please refer to your hardware manufacturer and  for current compatibility information. Some system components such as mobile chipsets, integrated, and AGP graphics cards may be incompatible. Unlisted specifications may not be supported by publisher.  Other requirements: Installation and online play requires log-in to Rockstar Games account (minimum age varies) network; internet connection required for activation, online play, and periodic entitlement verification; software installations required including Rockstar Games Launcher, DirectX, Chromium, and Microsoft Visual C++ 2008 sp1 Redistributable Package, and authentication and verification software that recognizes certain hardware attributes for entitlement, digital rights management, anti-cheat and moderation software, system, and other support purposes.  *Compatible PC and/or device required. 3D Audio via Windows Spatial Sound compatible audio systems</li></ul>', 'steam', '2026-09-16 10:48:53', '2026-09-16 02:48:53', '2026-09-16 02:48:53'),
	(2, 1, 'recommended', 'Windows 11', 'Intel® Core™ i5-9600K | AMD Ryzen™ 5 3600', 'NVIDIA GeForce® RTX 3060 (8GB VRAM) | AMD Radeon™ RX 6600XT (8GB VRAM)', '16 GB RAM', '105 GB available space', 16, NULL, '<strong>Recommended:</strong><br><ul class="bb_ul"><li>Requires a 64-bit processor and operating system<br></li><li><strong>OS:</strong> Windows 11<br></li><li><strong>Processor:</strong> Intel® Core™ i5-9600K | AMD Ryzen™ 5 3600<br></li><li><strong>Memory:</strong> 16 GB RAM<br></li><li><strong>Graphics:</strong> NVIDIA GeForce® RTX 3060 (8GB VRAM) | AMD Radeon™ RX 6600XT (8GB VRAM)<br></li><li><strong>Storage:</strong> 105 GB available space<br></li><li><strong>Sound Card:</strong> Windows Spatial Sound-compatible audio system; solution containing Dolby Atmos® support required for a Dolby Atmos® experience<br></li><li><strong>Additional Notes:</strong> SSD with DirectStorage-compatibility</li></ul>', 'steam', '2026-09-16 10:48:53', '2026-09-16 02:48:53', '2026-09-16 02:48:53'),
	(3, 2, 'minimum', '64-bit Windows 11', 'Core i5-8400 / Ryzen 5 2600', 'GeForce GTX 1660 / Radeon RX 5500 XT 8GB / Arc A580', '12 GB GB RAM', '70 GB available space', 12, NULL, '<strong>Minimum:</strong><br><ul class="bb_ul"><li>Requires a 64-bit processor and operating system<br></li><li><strong>OS:</strong> 64-bit Windows 11<br></li><li><strong>Processor:</strong> Core i5-8400 / Ryzen 5 2600<br></li><li><strong>Memory:</strong> 12 GB GB RAM<br></li><li><strong>Graphics:</strong> GeForce GTX 1660 / Radeon RX 5500 XT 8GB / Arc A580<br></li><li><strong>Storage:</strong> 70 GB available space</li></ul>', 'steam', '2026-09-16 11:06:30', '2026-09-16 03:06:30', '2026-09-16 03:06:30'),
