	(66, 36, 'recommended', 'Windows 10 version 21H1 (build 19043) or newer', 'Intel Core i5-3470', 'GeForce GTX 1050 (2GB), Radeon R9 380 (2GB)', '8 GB RAM', '9 GB available space', 8, NULL, '<strong>Recommended:</strong><br><ul class="bb_ul"><li>Requires a 64-bit processor and operating system<br></li><li><strong>OS:</strong> Windows 10 version 21H1 (build 19043) or newer<br></li><li><strong>Processor:</strong> Intel Core i5-3470<br></li><li><strong>Memory:</strong> 8 GB RAM<br></li><li><strong>Graphics:</strong> GeForce GTX 1050 (2GB), Radeon R9 380 (2GB)<br></li><li><strong>DirectX:</strong> Version 10<br></li><li><strong>Storage:</strong> 9 GB available space</li></ul>', 'steam', '2026-09-16 11:09:40', '2026-09-16 03:09:40', '2026-09-16 03:09:40'),
	(67, 37, 'minimum', 'Microsoft® Windows® /XP/Vista', 'Intel Pentium 4 2.4 GHz or Athlon 64 +2800 (Intel Pentium 4 3.0 GHz or AMD Athlon 64 +3000 recommended). Athlon XP series, such as the Athlon XP +2400, is not supported', 'NVIDIA GeForce 6600 or ATI Radeon 9800 or better (NVIDIA GeForce 7800 GTX or ATI Radeon X1950 XT or better recommended)', '1 GB RAM (2 GB RAM recommended)', NULL, 1, NULL, '<strong>Minimum: </strong><br>					<ul class="bb_ul"><li><strong>Supported OS: </strong>Microsoft® Windows® /XP/Vista<br>					</li><li><strong>DirectX Version: </strong>DirectX 9.0c (included) or higher<br>					</li><li><strong>Processor: </strong>Intel Pentium 4 2.4 GHz or Athlon 64 +2800 (Intel Pentium 4 3.0 GHz or AMD Athlon 64 +3000 recommended). Athlon XP series, such as the Athlon XP +2400, is not supported<br>					</li><li><strong>Graphics: </strong>NVIDIA GeForce 6600 or ATI Radeon 9800 or better (NVIDIA GeForce 7800 GTX or ATI Radeon X1950 XT or better recommended)<br>					</li><li><strong>Memory: </strong>1 GB RAM (2 GB RAM recommended)<br>					</li><li><strong>Sound: </strong>DirectX version 9.0c-compatible sound card<br>					</li><li><strong>Hard Drive: </strong>15 GB Free</li></ul>', 'steam', '2026-09-16 11:09:41', '2026-09-16 03:09:41', '2026-09-16 03:09:41'),
